DROP TABLE IF EXISTS `lottery_odds`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `lottery_odds` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `tenant_id` bigint unsigned NOT NULL DEFAULT '1',
  `lottery_id` bigint unsigned NOT NULL,
  `category_id` bigint unsigned DEFAULT NULL,
  `category` varchar(80) NOT NULL,
  `name` varchar(120) NOT NULL,
  `min_bet` decimal(12,4) DEFAULT NULL,
  `odds_limit` decimal(12,4) DEFAULT NULL,
  `single_bet_limit` decimal(14,2) DEFAULT NULL,
  `single_item_limit` decimal(14,2) DEFAULT NULL,
  `odds` decimal(12,4) DEFAULT NULL,
  `offline_rebate` decimal(10,4) DEFAULT NULL,
  `status` tinyint NOT NULL DEFAULT '1',
  `sort` int NOT NULL DEFAULT '0',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_odds_lottery_code` (`lottery_id`,`category`,`name`),
  KEY `idx_odds_lottery` (`lottery_id`,`status`,`sort`),
  KEY `idx_odds_tree` (`lottery_id`,`category_id`,`sort`)
) ENGINE=InnoDB AUTO_INCREMENT=285 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

