CREATE TABLE `user_stop_drops` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `tenant_id` bigint unsigned NOT NULL,
  `site_id` bigint unsigned NOT NULL,
  `user_id` bigint unsigned NOT NULL,
  `bet_detail_id` bigint unsigned DEFAULT NULL,
  `lottery` varchar(20) NOT NULL,
  `issue_no` varchar(40) NOT NULL,
  `number_text` text NOT NULL,
  `play_type` varchar(80) NOT NULL DEFAULT '',
  `stop_type` varchar(10) NOT NULL DEFAULT 'none',
  `original_amount` decimal(12,2) NOT NULL DEFAULT '0.00',
  `actual_amount` decimal(12,2) NOT NULL DEFAULT '0.00',
  `stop_amount` decimal(12,2) NOT NULL DEFAULT '0.00',
  `original_odds` decimal(10,3) DEFAULT NULL,
  `actual_odds` decimal(10,3) DEFAULT NULL,
  `drop_odds` decimal(10,3) DEFAULT NULL,
  `source_text` text,
  `placed_at` datetime NOT NULL,
  `created_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_stop_drop_user_time` (`site_id`,`user_id`,`placed_at`),
  KEY `idx_stop_drop_filters` (`site_id`,`user_id`,`lottery`,`stop_type`,`play_type`)
) ENGINE=InnoDB AUTO_INCREMENT=136 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
